{
  "name": "游戏手柄/操纵杆控制器",
  "name_en": "Joystick / Game Controller",
  "manufacturer": "",
  "description": "一种带按键、摇杆或扳机轴的手持控制器，部分型号还带陀螺仪。设备可作为 Linux 输入设备读取，用于实验中的机器人或小车手动遥控，以及按键、轴和转向/油门控制映射配置。",
  "description_en": "A handheld controller with buttons, sticks, and trigger axes, with some models also providing a gyroscope. It is used as a Linux input device for manual control of robots or small vehicles in lab setups, and for configuring button, axis, steering, and throttle mappings.",
  "tag_hints": [
    "teleoperation control",
    "joystick input",
    "game controller",
    "button and axis mapping",
    "robot car steering",
    "throttle control",
    "gyroscope input"
  ],
  "actions": [
    {
      "action_name": "auto-poll",
      "description": "轮询手柄输入。",
      "description_en": "Poll joystick inputs."
    },
    {
      "action_name": "get_button_press",
      "description": "获取被按下的按钮输入。",
      "description_en": "Get a pressed button input."
    },
    {
      "action_name": "get_axis_move",
      "description": "获取轴移动输入。",
      "description_en": "Get an axis movement input."
    },
    {
      "action_name": "auto-clear_scr",
      "description": "清除交互配置界面显示。",
      "description_en": "Clear the interactive configuration screen."
    },
    {
      "action_name": "auto-create_joystick",
      "description": "创建手柄控制映射配置。",
      "description_en": "Create a joystick control mapping configuration."
    },
    {
      "action_name": "auto-init_js_device",
      "description": "初始化物理手柄输入设备。",
      "description_en": "Initialize the physical joystick input device."
    },
    {
      "action_name": "auto-init_polling_js",
      "description": "初始化手柄输入轮询。",
      "description_en": "Initialize joystick input polling."
    },
    {
      "action_name": "auto-find_gyro",
      "description": "检测手柄是否带有陀螺仪输入。",
      "description_en": "Detect whether the controller provides gyroscope input."
    },
    {
      "action_name": "get_code_from_button",
      "description": "获取按钮代码。",
      "description_en": "Get the button code."
    },
    {
      "action_name": "auto-explain_config",
      "description": "说明手柄配置选项。",
      "description_en": "Explain the controller configuration options."
    },
    {
      "action_name": "auto-name_buttons",
      "description": "命名手柄按钮。",
      "description_en": "Name the controller buttons."
    },
    {
      "action_name": "auto-print_config",
      "description": "打印当前手柄映射配置。",
      "description_en": "Print the current controller mapping configuration."
    },
    {
      "action_name": "auto-name_axes",
      "description": "命名手柄控制轴。",
      "description_en": "Name the controller axes."
    },
    {
      "action_name": "auto-write_python_class_file",
      "description": "写出手柄映射定义文件。",
      "description_en": "Write a controller mapping definition file."
    },
    {
      "action_name": "auto-map_control_axis",
      "description": "将控制轴映射到指定控制功能。",
      "description_en": "Map a control axis to a specified control function."
    },
    {
      "action_name": "auto-map_steering_throttle",
      "description": "映射转向与油门控制。",
      "description_en": "Map steering and throttle controls."
    },
    {
      "action_name": "auto-map_button_controls",
      "description": "映射按钮控制功能。",
      "description_en": "Map button controls to functions."
    },
    {
      "action_name": "auto-revisit_topic",
      "description": "重新进入某个配置主题。",
      "description_en": "Revisit a configuration topic."
    },
    {
      "action_name": "get_axis_action",
      "description": "获取轴对应的控制动作。",
      "description_en": "Get the control action assigned to an axis."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭手柄轮询或配置流程。",
      "description_en": "Shut down joystick polling or the configuration workflow."
    },
    {
      "action_name": "auto-parse_args",
      "description": "解析手柄配置参数。",
      "description_en": "Parse controller setup arguments."
    },
    {
      "action_name": "auto-run",
      "description": "运行手柄交互式配置流程。",
      "description_en": "Run the interactive joystick setup workflow."
    }
  ]
}

